#include "json.hpp"
#include <fstream>
#include <iostream>
#include <bitset>
#include <vector>
#include <map>
#include <cmath>
#include <algorithm>
using namespace std;using J=nlohmann::json;using Bits=bitset<1024>;using Resp=bitset<128>;
struct E{int f,d;vector<int>s;};
int main(int argc,char**argv){ifstream in(argv[1]);J z;in>>z;int v=z["v"],n=2*v+int(z["R"]);vector<E>A;for(auto e:z["A"])A.push_back({e[0],e[1],e[2].get<vector<int>>()});int N=A.size();vector<Bits>F;for(auto f:z["frames"]){Bits b;for(int i:f)b[i]=1;F.push_back(b);}vector<int>dim;for(auto f:z["frames"]){double a[130][8]={};int r=0;for(int i=0;i<f.size();i++)for(int k=0;k<8;k++)a[i][k]=z["lines"][int(f[i])][k];for(int c=0;c<8;c++){int p=r;while(p<f.size()&&abs(a[p][c])<1e-8)p++;if(p==f.size())continue;for(int k=0;k<8;k++)swap(a[p][k],a[r][k]);double q=a[r][c];for(int k=c;k<8;k++)a[r][k]/=q;for(int i=r+1;i<f.size();i++){q=a[i][c];for(int k=c;k<8;k++)a[i][k]-=q*a[r][k];}r++;}dim.push_back(r);}
vector<Resp>R(n);for(int t=0;t<v;t++)R[v+t][t]=1;auto rev=[&](auto e){for(int s:e[2])R[s]^=R[int(e[1])];};for(int i=int(z["B"].size())-1;i>=0;i--)rev(z["B"][i]);for(int t=0;t<v;t++)for(int k:z["scatter"][t])R[int(z["ret"][k])]^=R[v+t];
struct Site{int j,f,d;};map<string,vector<Site>>sites;map<int,Resp>inj;
for(int i=N-1;i>=0;i--){auto e=A[i];vector<int>h=e.s;h.push_back(e.d);for(int d:h)if(d>=2*v)sites[R[d].to_string()].push_back({i,e.f,d});if(e.s.size()==1&&e.s[0]<v)inj[i]=R[e.d];for(int s:e.s)R[s]^=R[e.d];}
vector<vector<int>>past(N,vector<int>(v)),future(N,vector<int>(v));vector<int>cur=z["start"].get<vector<int>>();for(int i=0;i<N;i++){cur[A[i].d]=A[i].f;for(int s:A[i].s)cur[s]=A[i].f;for(int s=0;s<v;s++)past[i][s]=cur[s];}vector<int>next(v,1);for(int i=N-1;i>=0;i--){future[i]=next;for(int s:A[i].s)if(s<v)next[s]=A[i].f;}
vector<vector<pair<int,int>>>steps(n);auto add=[&](int idx,E e){steps[e.d].push_back({idx,e.f});for(int r:e.s)steps[r].push_back({idx,e.f});};for(int i=0;i<N;i++)add(i,A[i]);int idx=N;for(int r:z["ret"])steps[r].push_back({idx,-1});idx++;for(auto e:z["B"])add(idx++,{e[0],e[1],e[2].get<vector<int>>()});for(auto e:z["C"])add(idx++,{e[0],e[1],e[2].get<vector<int>>()});for(int r=0;r<n;r++)steps[r].push_back({idx,int(z["final"][r])});
auto regprof=[&](int r,const vector<int>&skip,Site at){vector<int>H(9);int c=z["start"][r];bool inserted=false;auto visit=[&](int f){if((F[c]&~F[f]).any())return false;int d=dim[f]-dim[c];if(d)H[d]++;c=f;return true;};for(auto [i,f]:steps[r]){if(!inserted&&i>at.j&&at.j>=0){if(!visit(at.f))return vector<int>{};inserted=true;}if(find(skip.begin(),skip.end(),i)!=skip.end())continue;if(f==-1)H[dim[c]]++;else if(!visit(f))return vector<int>{};}return H;};vector<vector<int>>baseR;map<int,int>base;for(int r=0;r<n;r++){auto h=regprof(r,{}, {-1,0,0});baseR.push_back(h);for(int k=1;k<=8;k++)base[k]+=h[k];}
J out;out["base"]=base;out["candidates"]=J::array();long long tried=0,subsets=0;map<int,vector<int>>grp;for(auto [i,r]:inj)grp[A[i].s[0]].push_back(i);
for(auto [source,ids]:grp){int m=ids.size();for(unsigned mask=1;mask<(1u<<m);mask++){Resp rs;vector<int>skip;for(int k=0;k<m;k++)if(mask>>k&1){rs^=inj[ids[k]];skip.push_back(ids[k]);}subsets++;for(auto at:sites[rs.to_string()]){if(!F[at.f][source]||find(skip.begin(),skip.end(),at.j)!=skip.end())continue;tried++;vector<int>regs{source,at.d};for(int i:skip)regs.push_back(A[i].d);sort(regs.begin(),regs.end());regs.erase(unique(regs.begin(),regs.end()),regs.end());map<int,int>h=base;bool ok=true;for(int r:regs){auto hh=regprof(r,skip,(r==source||r==at.d)?at:Site{-1,0,0});if(hh.empty()){ok=false;break;}for(int k=1;k<=8;k++)h[k]+=hh[k]-baseR[r][k];}if(!ok)continue;double gain=0;J delta=J::object();for(int k=1;k<=8;k++){int d=h[k]-base[k];gain+=d*k*log(k);if(d)delta[to_string(k)]=d;}if(gain>1e-8)out["candidates"].push_back({{"remove",skip},{"after",at.j},{"event",{at.f,at.d,J::array({source})}},{"delta",delta},{"gain",gain}});}}}out["subsets"]=subsets;out["tried"]=tried;sort(out["candidates"].begin(),out["candidates"].end(),[](auto&a,auto&b){return double(a["gain"])>double(b["gain"]);});cout<<out.dump(2)<<endl;}
